-- Table structure for table `xt_giathuong`
--

DROP TABLE IF EXISTS `xt_giathuong`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `xt_giathuong` (
  `id_gt` int NOT NULL AUTO_INCREMENT,
  `cccd` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT 'Mã CCCD của thí sinh',
  `cap_giai` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT 'Quốc gia hoặc Tỉnh',
  `doi_tuong` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT 'VD: Học sinh giỏi',
  `ma_mon` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT 'Mã môn đạt giải (TO, VA, N1, SU...)',
  `loai_giai` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT 'Nhất, Nhì, Ba, Khuyến khích',
  `diem_cong_co_mon` double NOT NULL DEFAULT '0' COMMENT 'Cộng nếu THXT có môn đạt giải',
  `diem_cong_khong_mon` double NOT NULL DEFAULT '0' COMMENT 'Cộng nếu THXT KHÔNG có môn đạt giải',
  PRIMARY KEY (`id_gt`)
) ENGINE=InnoDB AUTO_INCREMENT=290 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

